// 仅用于独立 Portal 设计预览；从 Owner 接受的 V2 原型派生，不调用真实 API。
/** @param {ShadowRoot} root @param {'people'|'roles'} initialPage @param {(page: string) => void} onPageChange */
export function mountPermissionPrototype(root, initialPage = 'people', onPageChange = () => {}) {
const handlers=[];
const initialOverflow=root.ownerDocument.body.style.overflow;
const listen=(type,handler)=>{root.addEventListener(type,handler);handlers.push([type,handler])};


// 独立原型：合成目录、合成人员；不连接 API、不保存、不操作真实授权。
const icon=(name)=>{const paths={search:'<circle cx="8.5" cy="8.5" r="5.5"/><path d="m13 13 4 4"/>',plus:'<path d="M10 3v14M3 10h14"/>',reset:'<path d="M3 7a7 7 0 1 1 0 6M3 2v5h5"/>',edit:'<path d="m13 3 4 4M4 13 14 3l3 3L7 16H3Z"/>',trash:'<path d="M3 5h14M7 5V2h6v3M5 5l1 13h8l1-13M8 8v7m4-7v7"/>',folder:'<path d="M2 5h6l2 2h8v10H2Z"/>'};return '<svg class="icon '+(name==='folder'?'folder':'')+'" viewBox="0 0 20 20" aria-hidden="true">'+(paths[name]||'')+'</svg>'};
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const departments=[{id:'all',name:'海滨药业',level:0,parent:null},{id:'qc',name:'质量控制部',level:1,parent:'all'},{id:'lab1',name:'化验一组',level:2,parent:'qc'},{id:'lab2',name:'无菌检验组',level:2,parent:'qc'},{id:'qa',name:'质量管理部',level:1,parent:'all'},{id:'store',name:'仓储部',level:1,parent:'all'},{id:'admin',name:'综合管理部',level:1,parent:'all'}];
const directory=[{name:'平台基础',items:[{id:'home',name:'工作台',actions:['查看']},{id:'people',name:'人员信息',actions:['查看','新增','编辑','停用']},{id:'roles',name:'权限管理',actions:['查看','新增','编辑','关联岗位']}]},{name:'LIMS 实验室',items:[{id:'sample',name:'样品管理',actions:['查看','登记','编辑']},{id:'test',name:'检验记录',actions:['查看','录入','提交']},{id:'review',name:'检验复核',actions:['查看','复核']},{id:'quality',name:'质量审核',actions:['查看','审核']}]},{name:'仓储管理（扩展示例）',items:[{id:'stock',name:'库存台账',actions:['查看']},{id:'move',name:'出入库记录',actions:['查看','登记'] }]}];
const keys=(id,acts)=>acts.map(a=>id+':'+a);
let roles=[
 {id:'r1',name:'检验员',created:'2026-10-01',desc:'登记样品、录入与提交本人负责的检验记录。',perms:['home:查看',...keys('sample',['查看','登记']),...keys('test',['查看','录入','提交'])]},
 {id:'r2',name:'检验复核员',created:'2026-10-01',desc:'查看岗位关联检验组的记录，完成检验复核。',perms:['home:查看','test:查看',...keys('review',['查看','复核'])]},
 {id:'r3',name:'QA 审核员',created:'2026-10-01',desc:'在岗位授权范围内查看检验结果并进行质量审核。',perms:['home:查看','test:查看',...keys('quality',['查看','审核'])]},
 {id:'r4',name:'仓库操作员',created:'2026-10-03',desc:'查看库存台账，登记岗位所属仓库的出入库记录。',perms:['home:查看','stock:查看',...keys('move',['查看','登记'])]},
 {id:'r5',name:'人员管理员',created:'2026-10-03',desc:'维护所负责部门的人员信息与任职岗位。',perms:['home:查看',...keys('people',['查看','新增','编辑','停用'])]},
 {id:'r6',name:'权限管理员',created:'2026-10-03',desc:'维护角色权限与岗位关联，不自动取得业务签署权限。',perms:['home:查看',...keys('roles',['查看','新增','编辑','关联岗位'])]}
];
let positions=[{id:'p1',dept:'lab1',name:'检验员',scope:'化验一组 · 本人负责记录（口径待确认）',roleIds:['r1']},{id:'p2',dept:'lab1',name:'复核员',scope:'化验一组 · 复核范围',roleIds:['r2']},{id:'p3',dept:'lab2',name:'检验员',scope:'无菌检验组 · 本人负责记录（口径待确认）',roleIds:['r1']},{id:'p4',dept:'qa',name:'QA 审核员',scope:'质量管理部 · 获准审核范围',roleIds:['r3']},{id:'p5',dept:'store',name:'仓库管理员',scope:'仓储部 · 一号仓库',roleIds:['r4']},{id:'p6',dept:'admin',name:'人事专员',scope:'综合管理部 · 人员维护范围',roleIds:['r5']},{id:'p7',dept:'admin',name:'权限管理专员',scope:'已获准管理的角色与岗位',roleIds:['r6']}];
let people=[['HB001','张明','138****2001',['p1']],['HB002','李晨','138****2002',['p1']],['HB003','王敏','138****2003',['p2']],['HB004','赵宁','138****2004',['p3']],['HB005','刘洋','138****2005',['p3']],['HB006','陈静','138****2006',['p4']],['HB007','周杰','138****2007',['p5']],['HB008','孙悦','138****2008',['p6']],['HB009','郑林','138****2009',['p7']],['HB010','何佳','138****2010',['p1','p3']]].map(([id,name,phone,positionIds])=>({id,name,phone,positionIds,active:true}));
let state={page:initialPage,dept:'all',orgQuery:'',query:'',phone:'',role:'',position:'',includeChildren:true,pageNo:1,pageSize:10,roleQuery:''};
let modalState=null,returnFocus=null,toastTimer;
const $=sel=>root.querySelector(sel);
const deptName=id=>departments.find(d=>d.id===id)?.name||'';
const pos=id=>positions.find(p=>p.id===id);
const personPositions=person=>person.positionIds.map(pos).filter(Boolean);
const personRoles=person=>[...new Set(personPositions(person).flatMap(p=>p.roleIds))].map(id=>roles.find(r=>r.id===id)).filter(Boolean);
const tags=list=>list.length?list.map(r=>'<span class="role-tag">'+esc(r.name)+'</span>').join(''):'<span class="subtle">未关联角色</span>';
const roleOptions=(value='')=>'<option value="">全部角色</option>'+roles.map(r=>'<option value="'+r.id+'" '+(r.id===value?'selected':'')+'>'+esc(r.name)+'</option>').join('');
function inDept(id,root,include=true){if(root==='all')return true;if(id===root)return true;if(!include)return false;let d=departments.find(x=>x.id===id);while(d?.parent){if(d.parent===root)return true;d=departments.find(x=>x.id===d.parent)}return false}
function filteredPeople(){return people.filter(p=>p.name.includes(state.query)&&p.phone.includes(state.phone)&&(!state.role||personRoles(p).some(r=>r.id===state.role))&&(!state.position||personPositions(p).some(x=>x.name===state.position))&&personPositions(p).some(x=>inDept(x.dept,state.dept,state.includeChildren)))}
function pager(total){const max=Math.max(1,Math.ceil(total/state.pageSize));state.pageNo=Math.min(state.pageNo,max);return '<div class="pager"><span>共 '+total+' 条</span><button class="page-btn" data-action="prev" aria-label="上一页" '+(state.pageNo===1?'disabled':'')+'>‹</button><button class="page-btn current" aria-label="当前页">'+state.pageNo+'</button><button class="page-btn" data-action="next" aria-label="下一页" '+(state.pageNo>=max?'disabled':'')+'>›</button><select aria-label="每页条数" id="page-size">'+[5,10,20].map(n=>'<option '+(state.pageSize===n?'selected':'')+' value="'+n+'">'+n+' 条/页</option>').join('')+'</select></div>'}
function orgTree(){return departments.filter(d=>!state.orgQuery||d.name.includes(state.orgQuery)).map(d=>'<button class="tree-btn '+(d.id===state.dept?'selected':'')+'" style="padding-left:'+(d.level*15+6)+'px" data-dept="'+d.id+'" aria-pressed="'+(d.id===state.dept)+'"><span class="chev">'+(['all','qc'].includes(d.id)?'▾':'')+'</span>'+icon('folder')+esc(d.name)+'<span class="count">'+people.filter(p=>personPositions(p).some(x=>inDept(x.dept,d.id,true))).length+'</span></button>').join('')||'<p class="subtle">未找到组织</p>'}
function renderPeople(){const list=filteredPeople();const page= list.slice((Math.min(state.pageNo,Math.max(1,Math.ceil(list.length/state.pageSize)))-1)*state.pageSize,Math.min(state.pageNo,Math.max(1,Math.ceil(list.length/state.pageSize)))*state.pageSize);return '<div class="person-layout"><aside class="panel org" aria-label="组织架构"><div class="panel-title"><i class="accent"></i>组织架构</div><div class="org-search">'+icon('search')+'<input id="org-search" aria-label="搜索组织" placeholder="搜索组织名称" value="'+esc(state.orgQuery)+'"></div><div class="org-tree" id="org-tree">'+orgTree()+'</div><div class="org-foot">组织与岗位将在后续统一维护<br>此处用于筛选人员与查看任职</div></aside><section class="panel workspace" aria-label="人员信息列表"><div class="panel-title"><i class="accent"></i>人员信息<small>'+esc(deptName(state.dept))+'</small><span class="right-note">角色随岗位关联</span></div><form class="toolbar" id="people-search"><input name="name" aria-label="人员名称筛选" placeholder="请输入人员名称" value="'+esc(state.query)+'"><input name="phone" aria-label="手机号筛选" placeholder="请输入手机号" value="'+esc(state.phone)+'"><select name="position" aria-label="岗位筛选"><option value="">全部岗位</option>'+[...new Set(positions.map(p=>p.name))].map(n=>'<option '+(state.position===n?'selected':'')+'>'+esc(n)+'</option>').join('')+'</select><select name="role" aria-label="角色筛选">'+roleOptions(state.role)+'</select><button type="submit" class="btn primary">'+icon('search')+'搜索</button><button type="button" class="btn" data-action="reset-search">重置</button><div class="push"><label class="checkline"><input type="checkbox" id="include-children" '+(state.includeChildren?'checked':'')+'>包含下级</label><button type="button" class="btn primary" data-action="add-person">'+icon('plus')+'新增人员</button></div></form><div class="table-wrap"><table class="data-table" aria-label="人员信息"><colgroup><col style="width:9%"><col style="width:11%"><col style="width:15%"><col style="width:15%"><col style="width:15%"><col style="width:19%"><col style="width:16%"></colgroup><thead><tr>'+['ID','人员名称','部门','岗位','手机号','角色','操作'].map(s=>'<th scope="col">'+s+'</th>').join('')+'</tr></thead><tbody>'+page.map(p=>{const ps=personPositions(p);return '<tr class="'+(!p.active?'muted-row':'')+'"><td class="id">'+esc(p.id)+'</td><td class="name">'+esc(p.name)+'</td><td>'+[...new Set(ps.map(x=>deptName(x.dept)))].map(esc).join('<br>')+'</td><td>'+ps.map((x,i)=>esc(x.name)+(i?' <span class="subtle">兼任</span>':'')).join('<br>')+'</td><td class="phone">'+esc(p.phone)+'</td><td>'+tags(personRoles(p))+'</td><td><div class="actions"><button class="text-btn" data-action="edit-person" data-id="'+p.id+'">'+icon('edit')+'编辑</button><button class="text-btn" data-action="person-detail" data-id="'+p.id+'">详情</button></div></td></tr>'}).join('')+(page.length?'':'<tr><td colspan="7" class="empty">暂无符合条件的人员，请调整筛选条件。</td></tr>')+'</tbody></table></div>'+pager(list.length)+'</section></div>'}
function renderRoles(){const list=roles.filter(r=>r.name.includes(state.roleQuery));const max=Math.max(1,Math.ceil(list.length/state.pageSize));state.pageNo=Math.min(state.pageNo,max);const page=list.slice((state.pageNo-1)*state.pageSize,state.pageNo*state.pageSize);return '<section class="panel roles-panel" aria-label="权限管理列表"><div class="panel-title"><i class="accent"></i>权限管理<span class="right-note">配置角色权限，再关联到部门岗位</span></div><form class="toolbar" id="role-search"><input name="roleName" aria-label="角色名称筛选" placeholder="请输入角色名称" value="'+esc(state.roleQuery)+'"><button class="btn primary" type="submit">'+icon('search')+'搜索</button><button class="btn" data-action="reset-search" type="button">重置</button><div class="push"><button class="btn primary" data-action="add-role" type="button">'+icon('plus')+'添加角色</button></div></form><div class="table-wrap"><table class="data-table role-list-table" aria-label="角色权限"><colgroup><col style="width:65px"><col style="width:17%"><col style="width:170px"><col><col style="width:235px"></colgroup><thead><tr>'+['序号','角色','创建时间','描述','操作'].map(s=>'<th scope="col">'+s+'</th>').join('')+'</tr></thead><tbody>'+page.map((r,i)=>'<tr><td class="id">'+((state.pageNo-1)*state.pageSize+i+1)+'</td><td class="name">'+esc(r.name)+'</td><td>'+esc(r.created)+'</td><td class="desc">'+esc(r.desc)+'</td><td><div class="actions"><button class="text-btn" data-action="edit-role" data-id="'+r.id+'">'+icon('edit')+'编辑</button><button class="text-btn" data-action="map-role" data-id="'+r.id+'">关联岗位</button><button class="text-btn" data-action="delete-role" data-id="'+r.id+'">'+icon('trash')+'删除</button></div></td></tr>').join('')+(page.length?'':'<tr><td colspan="5" class="empty">暂无符合条件的角色</td></tr>')+'</tbody></table></div>'+pager(list.length)+'<div class="footnote">新增岗位可关联已有角色；新增业务功能需单独配置权限。</div></section>'}
function render(){ $('#main').innerHTML=state.page==='people'?renderPeople():renderRoles();root.querySelectorAll('[data-page]').forEach(b=>{b.classList.toggle('active',b.dataset.page===state.page);if(b.dataset.page===state.page)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')})}
function toast(msg){clearTimeout(toastTimer);$('#notice').innerHTML='<div class="toast">'+esc(msg)+'</div>';toastTimer=setTimeout(()=>$('#notice').innerHTML='',3600)}
function openModal(title,body,footer,{wide=false}={}){if(!$('#overlay').firstElementChild)returnFocus=root.activeElement;$('#overlay').innerHTML='<div class="modal-backdrop"><section class="modal '+(wide?'wide':'')+'" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-head"><h2 id="modal-title">'+esc(title)+'</h2><button class="modal-close" data-action="close-modal" aria-label="关闭弹窗">×</button></header><div class="modal-body">'+body+'</div><footer class="modal-foot"><small>原型演示 · 仅在本页内存中保存</small>'+footer+'</footer></section></div>';root.host.classList.add('has-modal');root.ownerDocument.body.style.overflow='hidden';$('.modal-close').focus()}
function closeModal(){ $('#overlay').innerHTML='';root.host.classList.remove('has-modal');root.ownerDocument.body.style.overflow=initialOverflow;modalState=null;if(returnFocus?.isConnected)returnFocus.focus();else $('[data-page="'+state.page+'"]').focus()}
const cancelSave=(action)=>'<button class="btn" data-action="close-modal">取消</button><button class="btn primary" data-action="'+action+'">保存</button>';
function deptOptions(selected){return '<option value="">请选择部门</option>'+departments.filter(d=>positions.some(p=>p.dept===d.id)).map(d=>'<option value="'+d.id+'" '+(d.id===selected?'selected':'')+'>'+esc(d.name)+'</option>').join('')}
function positionOptions(deptId,selected){return '<option value="">请选择岗位</option>'+positions.filter(p=>p.dept===deptId).map(p=>'<option value="'+p.id+'" '+(p.id===selected?'selected':'')+'>'+esc(p.name)+'</option>').join('')}
function assignmentForm(id,index){const p=pos(id),department=modalState.assignmentDepts?.[index]??p?.dept;return '<div class="assignment-block position-card" data-assignment="'+index+'"><div class="position-title">'+(index===0?'主要任职':'兼任岗位')+(index?'<button class="text-btn" data-action="remove-assignment" data-index="'+index+'">移除</button>':'')+'</div><div class="form-grid"><label class="field"><span><i class="req">*</i>部门</span><select aria-label="'+(index===0?'部门':'兼任部门 '+index)+'" data-assignment-dept="'+index+'">'+deptOptions(department)+'</select></label><label class="field"><span><i class="req">*</i>岗位</span><select aria-label="'+(index===0?'岗位':'兼任岗位 '+index)+'" data-assignment-position="'+index+'">'+positionOptions(department,id)+'</select></label></div></div>'}
function derivedRoles(ids){return ids.filter(Boolean).map(id=>{const p=pos(id);return '<div style="margin-top:6px"><span class="subtle">'+esc(deptName(p.dept))+' / '+esc(p.name)+'：</span>'+tags(p.roleIds.map(rid=>roles.find(r=>r.id===rid)).filter(Boolean))+'</div>'}).join('')||'<span class="subtle">选择部门与岗位后，自动显示对应角色</span>'}
function openPerson(id){const p=people.find(x=>x.id===id);modalState={type:'person',id:p?.id,assignments:p?[...p.positionIds]:[''],assignmentDepts:p?p.positionIds.map(id=>pos(id)?.dept||''):['']};const nextId='HB'+String(Math.max(0,...people.map(x=>Number(x.id.slice(2))))+1).padStart(3,'0');openModal(p?'编辑人员':'新增人员','<div class="form-grid"><label class="field"><span>ID</span><input id="person-id" value="'+esc(p?.id||nextId)+'" readonly style="background:#f7f9fc;color:#9aa4b4"></label><label class="field"><span><i class="req">*</i>人员名称</span><input id="person-name" value="'+esc(p?.name||'')+'" placeholder="请输入人员名称" maxlength="30"></label><label class="field"><span><i class="req">*</i>手机号</span><input id="person-phone" value="'+esc(p?.phone||'')+'" placeholder="演示可用 138****2999" maxlength="20"></label><label class="field"><span>人员状态</span><select id="person-active"><option value="true">启用</option><option value="false" '+(p&&!p.active?'selected':'')+'>停用</option></select></label><div class="field full"><span>部门与岗位</span><div id="assignment-forms">'+modalState.assignments.map(assignmentForm).join('')+'</div><button class="text-btn" data-action="add-assignment" style="align-self:flex-start">'+icon('plus')+'添加兼任岗位</button></div><div class="field full"><span>关联角色</span><div class="derived"><p>由所选岗位自动关联</p><div id="derived-roles">'+derivedRoles(modalState.assignments)+'</div></div></div></div><p class="validation" id="form-error" role="alert"></p>',cancelSave('save-person'))}
function refreshAssignments(){ $('#assignment-forms').innerHTML=modalState.assignments.map(assignmentForm).join('');$('#derived-roles').innerHTML=derivedRoles(modalState.assignments)}
function savePerson(){const name=$('#person-name').value.trim(),phone=$('#person-phone').value.trim(),ids=modalState.assignments;if(!name||!phone||ids.some(id=>!id)){ $('#form-error').textContent='请填写人员名称、手机号，并选择完整的部门与岗位。';return}if(!/^1[0-9*]{10}$/.test(phone)){ $('#form-error').textContent='请输入 11 位手机号或演示脱敏号码，如 138****2999。';return}if(new Set(ids).size!==ids.length){$('#form-error').textContent='同一人员不能重复选择同一个岗位。';return}const old=people.find(p=>p.id===modalState.id);const value={id:$('#person-id').value,name,phone,positionIds:[...ids],active:$('#person-active').value==='true'};if(old){const changed=old.positionIds.join()!==ids.join()||old.active!==value.active;if(changed){modalState.pending=value;openModal('确认任职变更','<p class="scope-note">请核对岗位及关联角色的变化。本次仅演示页面效果。</p><div class="section-label">变更前</div><div class="derived">'+derivedRoles(old.positionIds)+'</div><div class="section-label">变更后'+(!value.active?' · 人员停用':'')+'</div><div class="derived">'+derivedRoles(value.positionIds)+'</div><p class="scope-note" style="margin-top:16px">正式生效须由同一后端核验任职、具体业务范围及所需审批。</p>','<button class="btn" data-action="back-person">返回修改</button><button class="btn primary" data-action="confirm-person">确认变更</button>');return}Object.assign(old,value)}else people.push(value);closeModal();render();toast('人员信息已在原型中更新')}
function personDetail(id){const p=people.find(x=>x.id===id);modalState={type:'detail',id};openModal('人员详情','<div class="detail-name"><div class="detail-avatar">'+esc(p.name.slice(-1))+'</div><div><strong>'+esc(p.name)+'</strong><small>'+esc(p.id)+'</small></div><span class="role-tag '+(p.active?'green':'gray')+'" style="margin-left:auto">'+(p.active?'启用':'停用')+'</span></div><div class="detail-grid"><div><span>手机号</span>'+esc(p.phone)+'</div><div><span>任职数量</span>'+p.positionIds.length+' 个岗位</div></div><div class="section-label">岗位与权限来源</div>'+personPositions(p).map((x,i)=>'<div class="detail-assignment"><b>'+esc(deptName(x.dept))+' / '+esc(x.name)+'</b> <span class="subtle">'+(i?'兼任':'主岗')+'</span><div style="margin-top:7px">'+tags(x.roleIds.map(rid=>roles.find(r=>r.id===rid)).filter(Boolean))+'</div><p>数据范围：'+esc(x.scope)+'</p></div>').join('')+'<p class="scope-note" style="margin-top:15px">角色按每条任职与范围分别匹配，兼任不会合并扩大业务范围。</p>','<button class="btn" data-action="close-modal">关闭</button><button class="btn primary" data-action="edit-person" data-id="'+p.id+'">编辑人员</button>')}
function permissionTree(query=''){const filtered=directory.map(a=>({...a,items:a.items.filter(i=>!query||i.name.includes(query)||a.name.includes(query))})).filter(a=>a.items.length);return filtered.map(a=>'<details class="perm-app" open><summary>'+esc(a.name)+'</summary>'+a.items.map(i=>'<div class="perm-row"><label class="checkline"><input type="checkbox" data-perm-group="'+i.id+'">'+esc(i.name)+'</label><div class="perm-actions">'+i.actions.map(act=>{const key=i.id+':'+act;return '<label class="checkline"><input type="checkbox" data-perm="'+esc(key)+'" '+(modalState.perms.has(key)?'checked':'')+'>'+esc(act)+'</label>'}).join('')+'</div></div>').join('')+'</details>').join('')||'<p class="subtle">未找到匹配的菜单与操作</p>'}
function scopeTable(roleId){const linked=positions.filter(p=>p.roleIds.includes(roleId));return '<div class="table-wrap"><table class="data-table scope-table" aria-label="角色关联的岗位与范围"><thead><tr><th>部门</th><th>岗位</th><th>具体数据范围</th></tr></thead><tbody>'+linked.map(p=>'<tr><td>'+esc(deptName(p.dept))+'</td><td>'+esc(p.name)+'</td><td>'+esc(p.scope)+'</td></tr>').join('')+(linked.length?'':'<tr><td colspan="3" class="empty" style="height:90px">暂无关联岗位，可在保存角色后配置</td></tr>')+'</tbody></table></div>'}
function roleTab(tab){modalState.tab=tab;root.querySelectorAll('[data-role-tab]').forEach(b=>b.classList.toggle('active',b.dataset.roleTab===tab));if(tab==='permissions'){$('#role-tab-content').innerHTML='<div class="permission-tools"><span>勾选角色可使用的菜单与操作</span><input id="permission-search" aria-label="搜索菜单权限" placeholder="搜索菜单 / 功能"></div><div id="permission-tree">'+permissionTree()+'</div>';syncPermissionChecks()}else $('#role-tab-content').innerHTML='<p class="scope-note">角色定义可执行的操作。具体部门、检验组或仓库范围由关联岗位确定。</p>'+scopeTable(modalState.id)+'<p class="scope-note" style="margin-top:15px">岗位维护后可继续关联角色；新增功能不会自动勾选。</p>';updatePermissionCount()}
function openRole(id){const r=roles.find(x=>x.id===id);modalState={type:'role',id:r?.id,perms:new Set(r?.perms||[]),tab:'permissions'};openModal(r?'编辑角色':'添加角色','<div class="form-grid"><label class="field full"><span><i class="req">*</i>角色名称</span><input id="role-name" value="'+esc(r?.name||'')+'" placeholder="请输入角色名称" maxlength="30"></label><label class="field full"><span>角色描述</span><textarea id="role-desc" placeholder="请输入角色描述" maxlength="200">'+esc(r?.desc||'')+'</textarea></label></div><div class="tabs" role="tablist" aria-label="角色配置"><button class="active" role="tab" aria-selected="true" data-role-tab="permissions">菜单与操作权限</button><button role="tab" aria-selected="false" data-role-tab="scope">关联岗位与范围</button></div><div class="permissions-box" id="role-tab-content"></div><p class="permission-summary" id="permission-count"></p><p class="validation" id="form-error" role="alert"></p>',cancelSave('save-role'),{wide:true});roleTab('permissions')}
function syncPermissionChecks(){root.querySelectorAll('[data-perm-group]').forEach(c=>{const item=directory.flatMap(a=>a.items).find(i=>i.id===c.dataset.permGroup);const selected=item.actions.filter(a=>modalState.perms.has(item.id+':'+a)).length;c.checked=selected===item.actions.length;c.indeterminate=selected>0&&selected<item.actions.length});updatePermissionCount()}
function updatePermissionCount(){if($('#permission-count'))$('#permission-count').textContent='已选择 '+modalState.perms.size+' 项操作权限 · 示例目录支持后续业务模块扩充'}
function saveRole(){const name=$('#role-name').value.trim(),desc=$('#role-desc').value.trim();if(!name){$('#form-error').textContent='请输入角色名称。';return}if(roles.some(r=>r.name===name&&r.id!==modalState.id)){ $('#form-error').textContent='角色名称已存在，请使用其他名称。';return}const r=roles.find(x=>x.id===modalState.id);if(r){Object.assign(r,{name,desc,perms:[...modalState.perms]})}else roles.push({id:'r'+Date.now(),name,desc,perms:[...modalState.perms],created:'2026-10-08'});closeModal();render();toast('角色配置已在原型中保存')}
function openMapping(id){const r=roles.find(x=>x.id===id);modalState={type:'mapping',id};openModal('关联岗位','<div class="readonly-line"><span>当前角色</span><b>'+esc(r.name)+'</b></div><p class="scope-note">勾选要关联的部门岗位。任职于这些岗位的人员将显示该角色，具体数据范围沿用各岗位设置。</p><div class="table-wrap"><table class="data-table map-table" aria-label="岗位关联"><colgroup><col style="width:44px"><col style="width:20%"><col style="width:20%"><col><col style="width:64px"></colgroup><thead><tr><th>选择</th><th>部门</th><th>岗位</th><th>数据范围</th><th>人数</th></tr></thead><tbody>'+positions.map(p=>'<tr><td><input type="checkbox" data-map="'+p.id+'" aria-label="关联 '+esc(deptName(p.dept))+' '+esc(p.name)+'" '+(p.roleIds.includes(id)?'checked':'')+'></td><td>'+esc(deptName(p.dept))+'</td><td>'+esc(p.name)+'</td><td class="subtle">'+esc(p.scope)+'</td><td>'+people.filter(x=>x.positionIds.includes(p.id)).length+'</td></tr>').join('')+'</tbody></table></div><p class="scope-note" style="margin:15px 0 0">此处预留岗位关联方式。部门、岗位及其范围后续由组织架构模块维护。</p>',cancelSave('save-mapping'),{wide:true})}
function saveMapping(){const selected=new Set([...root.querySelectorAll('[data-map]:checked')].map(c=>c.dataset.map));const changed=positions.filter(p=>p.roleIds.includes(modalState.id)!==selected.has(p.id));if(changed.length){modalState.selected=selected;const affected=people.filter(p=>p.positionIds.some(id=>changed.some(x=>x.id===id)));openModal('确认岗位关联变更','<p class="scope-note">以下 '+changed.length+' 个岗位的角色关联将变化，涉及 '+affected.length+' 名演示人员。</p><div class="table-wrap"><table class="data-table scope-table"><thead><tr><th>部门 / 岗位</th><th>变化</th><th>范围</th></tr></thead><tbody>'+changed.map(p=>'<tr><td>'+esc(deptName(p.dept)+' / '+p.name)+'</td><td>'+(selected.has(p.id)?'关联角色':'解除关联')+'</td><td>'+esc(p.scope)+'</td></tr>').join('')+'</tbody></table></div><p class="scope-note" style="margin-top:16px">正式系统须先核验变更资格及所需审批。本页仅演示关联结果。</p>','<button class="btn" data-action="back-mapping">返回修改</button><button class="btn primary" data-action="confirm-mapping">确认变更</button>',{wide:true});return}closeModal();toast('岗位关联没有变化')}
function deleteRole(id){const r=roles.find(x=>x.id===id);if(positions.some(p=>p.roleIds.includes(id))){toast('该角色已关联岗位，请先解除岗位关联后再删除');return}modalState={type:'delete-role',id};openModal('删除角色','<p class="confirm-copy">确定删除角色“'+esc(r.name)+'”？</p><p class="scope-note" style="margin-top:14px">仅删除本页的演示角色，刷新可恢复。</p>','<button class="btn" data-action="close-modal">取消</button><button class="btn primary" data-action="confirm-delete">确认删除</button>')}
listen('click',e=>{const page=e.target.closest('[data-page]');if(page){state.page=page.dataset.page;state.pageNo=1;render();onPageChange(state.page);return}const dep=e.target.closest('[data-dept]');if(dep){state.dept=dep.dataset.dept;state.pageNo=1;render();return}const tab=e.target.closest('[data-role-tab]');if(tab){root.querySelectorAll('[data-role-tab]').forEach(b=>b.setAttribute('aria-selected',String(b===tab)));roleTab(tab.dataset.roleTab);return}const b=e.target.closest('[data-action]');if(!b)return;const id=b.dataset.id;switch(b.dataset.action){case 'reset-search':if(state.page==='people')Object.assign(state,{query:'',phone:'',position:'',role:'',dept:'all',orgQuery:'',includeChildren:true,pageNo:1});else Object.assign(state,{roleQuery:'',pageNo:1});render();break;case 'add-person':openPerson();break;case 'edit-person':openPerson(id);break;case 'person-detail':personDetail(id);break;case 'close-modal':closeModal();break;case 'save-person':savePerson();break;case 'confirm-person':{const value=modalState.pending;Object.assign(people.find(p=>p.id===value.id),value);closeModal();render();toast('任职变更已在原型中更新');break}case 'back-person':{const value=modalState.pending;openPerson(value.id);$('#person-name').value=value.name;$('#person-phone').value=value.phone;$('#person-active').value=String(value.active);modalState.assignments=[...value.positionIds];modalState.assignmentDepts=value.positionIds.map(id=>pos(id)?.dept||'');refreshAssignments();break}case 'add-assignment':modalState.assignments.push('');modalState.assignmentDepts.push('');refreshAssignments();break;case 'remove-assignment':modalState.assignments.splice(Number(b.dataset.index),1);modalState.assignmentDepts.splice(Number(b.dataset.index),1);refreshAssignments();break;case 'add-role':openRole();break;case 'edit-role':openRole(id);break;case 'save-role':saveRole();break;case 'map-role':openMapping(id);break;case 'save-mapping':saveMapping();break;case 'back-mapping':{const saved=modalState.selected;openMapping(modalState.id);root.querySelectorAll('[data-map]').forEach(c=>c.checked=saved.has(c.dataset.map));break}case 'confirm-mapping':{const roleId=modalState.id;positions.forEach(p=>{p.roleIds=p.roleIds.filter(r=>r!==roleId);if(modalState.selected.has(p.id))p.roleIds.push(roleId)});closeModal();render();toast('岗位关联已更新，人员角色同步展示');break}case 'delete-role':deleteRole(id);break;case 'confirm-delete':roles=roles.filter(r=>r.id!==modalState.id);closeModal();render();toast('演示角色已删除，刷新可恢复');break;case 'prev':state.pageNo--;render();break;case 'next':state.pageNo++;render();break}});
listen('submit',e=>{e.preventDefault();if(e.target.id==='people-search'){const f=new FormData(e.target);Object.assign(state,{query:String(f.get('name')).trim(),phone:String(f.get('phone')).trim(),position:String(f.get('position')),role:String(f.get('role')),pageNo:1})}else if(e.target.id==='role-search'){state.roleQuery=String(new FormData(e.target).get('roleName')).trim();state.pageNo=1}render()});
listen('input',e=>{if(e.target.id==='org-search'){state.orgQuery=e.target.value.trim();$('#org-tree').innerHTML=orgTree()}if(e.target.id==='permission-search'){$('#permission-tree').innerHTML=permissionTree(e.target.value.trim());syncPermissionChecks()}});
listen('change',e=>{const c=e.target;if(c.id==='include-children'){state.includeChildren=c.checked;state.pageNo=1;render()}if(c.id==='page-size'){state.pageSize=Number(c.value);state.pageNo=1;render()}if(c.dataset.assignmentDept!==undefined){const i=Number(c.dataset.assignmentDept);modalState.assignments[i]='';modalState.assignmentDepts[i]=c.value;const select=$('[data-assignment-position="'+i+'"]');select.innerHTML=positionOptions(c.value,'');$('#derived-roles').innerHTML=derivedRoles(modalState.assignments)}if(c.dataset.assignmentPosition!==undefined){modalState.assignments[Number(c.dataset.assignmentPosition)]=c.value;$('#derived-roles').innerHTML=derivedRoles(modalState.assignments)}if(c.dataset.perm){if(c.checked)modalState.perms.add(c.dataset.perm);else modalState.perms.delete(c.dataset.perm);syncPermissionChecks()}if(c.dataset.permGroup){const item=directory.flatMap(a=>a.items).find(i=>i.id===c.dataset.permGroup);item.actions.forEach(a=>{const key=item.id+':'+a;if(c.checked)modalState.perms.add(key);else modalState.perms.delete(key)});root.querySelectorAll('[data-perm]').forEach(el=>el.checked=modalState.perms.has(el.dataset.perm));syncPermissionChecks()}});
listen('keydown',e=>{if(!$('.modal'))return;if(e.key==='Escape'){e.preventDefault();closeModal()}if(e.key==='Tab'){const focusable=[...$('.modal').querySelectorAll('button,input,select,textarea,[tabindex="0"]')].filter(el=>!el.disabled&&el.getClientRects().length);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&root.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&root.activeElement===last){e.preventDefault();first.focus()}}});
render();

return {
 setPage(page){if(state.page!==page){if(modalState)closeModal();state.page=page;state.pageNo=1;render()}},
 destroy(){clearTimeout(toastTimer);handlers.forEach(([type,handler])=>root.removeEventListener(type,handler));root.host.classList.remove('has-modal');root.ownerDocument.body.style.overflow=initialOverflow;root.innerHTML=''}
};

}
